	space: space {
		compatible = "zmk,behavior-hold-tap";
		label = "space";
		flavor = "balanced";
		tapping-term-ms = <170>;
		quick-tap-ms = <QUICK_TAP_MS>;
		retro-tap;
		#binding-cells = <2>;
		bindings = <&mo>, <&kp>;
	};
    */

    // Old thumb
    /*
	thumb: thumb {
		compatible = "zmk,behavior-hold-tap";
		label = "thumb";
		flavor = "balanced";
		tapping-term-ms = <TAPPING_TERM_MS>;
		quick-tap-ms = <QUICK_TAP_MS>;
		#binding-cells = <2>;
		bindings = <&mo>, <&kp>;
	};
    */

	esc_or_f4: esc_or_f4 {
		compatible = "zmk,behavior-mod-morph";
		label = "esc_or_f4";
		#binding-cells = <0>;
		bindings = <&kp ESC>, <&kp F4>;
		mods = <(MOD_LALT)>;
		keep-mods = <(MOD_LALT)>;
	};
};

custom_devicetree:
&caps_word {
	continue-list = <
		UNDERSCORE MINUS FSLH DOT COMMA SPACE GRAVE NUBS NON_US_HASH EQUAL RBKT PLUS
		BACKSPACE DELETE ENTER TAB ESCAPE
		LEFT_SHIFT RIGHT_SHIFT LEFT UP DOWN RIGHT HOME END PG_UP PG_DN
		N1 N2 N3 N4 N5 N6 N7 N8 N9 N0 F1 F2 F3 F4 F5 F6 F7 F8 F9 F10 F11 F12
	>;
};
